declare(strict_types=1);
/* Public Mackolik fixture JSON and server-rendered match pages. No account or private token. */
function pp_mackolik_competitions():array{return ['tr.1'=>'482ofyysbdbeoxauk19yg7tdt','en.1'=>'2kwbbcootiqqgmrzs6o5inle5','de.1'=>'6by3h89i2eykc341oz7lv1ddd','es.1'=>'34pl8szyvrbwcmfkuocjm3r6t','it.1'=>'1r097lpxe0xn03ihb7wi98kao','fr.1'=>'dm5ka0os1e3dxcp3vh05kmp33','ucl'=>'4oogyu6o156iphvdvphwpck10','uel'=>'4c1nfi2j1m731hcay25fcgndq','uecl'=>'c7b8o53flg36wbuevfzy3lb10'];}
function pp_mackolik_name(string $s):string{$n=pp_public_name($s);return ['alaves'=>'deportivoalaves','notforest'=>'nottinghamforest','manutd'=>'manchesterunited','manchesteryunited'=>'manchesterunited','manchesterc'=>'manchestercity','barcelona'=>'barcelona','realmadrit'=>'realmadrid','psv'=>'psveindhoven','athleticclub'=>'athletic'][$n]??$n;}
function pp_mackolik_day_url(string $date):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date))throw new RuntimeException('Invalid fixture date');return 'https://www.mackolik.com/perform/p0/ajax/components/competition/livescores/json?sports%5B%5D=Soccer&matchDate='.$date;}
function pp_mackolik_match_url(array $e,bool $comparison=false):string{$id=(string)($e['id']??'');$slug=(string)($e['matchSlug']??'');if(!preg_match('/^[a-z0-9]{20,30}$/D',$id)||!preg_match('/^[a-zA-Z0-9%_-]{1,180}$/D',$slug))throw new RuntimeException('Invalid match route');return 'https://www.mackolik.com/mac/'.$slug.'/'.($comparison?'karsilastirma/':'').$id;}
function pp_mackolik_page(string $url,array $cfg,DateTimeImmutable $now,?callable $fetcher=null):array{
 static $calls=0,$start=null;$start=$start??microtime(true);
 if(!preg_match('~^https://www\.mackolik\.com/(?:perform/p0/ajax/components/competition/livescores/json\?sports%5B%5D=Soccer&matchDate=\d{4}-\d{2}-\d{2}|mac/[a-zA-Z0-9%_-]{1,180}/(?:karsilastirma/)?[a-z0-9]{20,30}|takim/[a-zA-Z0-9%_-]{1,180}/kadro/[a-z0-9]{20,30})$~D',$url))throw new RuntimeException('Invalid Mackolik source URL');
 $file=$cfg['storage_dir'].'/source-mackolik-'.hash('sha256',$url).'.json';$old=pp_read($file);$at=strtotime($old['fetchedAt']??'')?:0;$ttl=str_contains($url,'/takim/')?900:(str_contains($url,'livescores/json')?300:(str_contains($url,'karsilastirma/')?900:90));
 if($at&&$at<=$now->getTimestamp()&&$now->getTimestamp()-$at<$ttl)return $old;
 try{if(isset($cfg['_lineup_deadline'])&&microtime(true)>$cfg['_lineup_deadline']-1)throw new RuntimeException('Lineup deadline');if(++$calls>($cfg['mackolik_request_budget']??4)||microtime(true)-$start>($cfg['mackolik_max_seconds']??14))throw new RuntimeException('Mackolik source budget exhausted');$net=$cfg;$net['source_hosts']=array_values(array_unique(array_merge($cfg['source_hosts']??[],['www.mackolik.com'])));$net['request_timeout_seconds']=isset($cfg['_lineup_deadline'])?max(1,min(4,(int)($cfg['_lineup_deadline']-microtime(true)))):4;$net['max_download_bytes']=2500000;$raw=$fetcher?$fetcher($url,$net):pp_fetch_raw($url,$net);if(is_array($raw))$raw=json_encode($raw,JSON_UNESCAPED_UNICODE);if(!is_string($raw)||strlen($raw)>2500000)throw new RuntimeException('Invalid Mackolik response');
  $out=['url'=>$url,'fetchedAt'=>$now->format(DATE_ATOM),'stale'=>false];if(str_contains($url,'livescores/json')){$j=json_decode($raw,true);if(!is_array($j)||($j['status']??'')!=='success'||!is_array($j['data']['matches']??null))throw new RuntimeException('Mackolik fixtures unavailable');$out['document']=$j;}else{if(!str_contains($raw,str_contains($url,'/takim/')?'p0c-team-information':'p0c-soccer-match-details-header'))throw new RuntimeException('Mackolik match unavailable');$out['html']=$raw;}pp_write($file,$out);return $out;
 }catch(Throwable $e){pp_lineup_trace('Mackolik','unavailable',$e->getMessage());if($at&&$at<=$now->getTimestamp()&&$now->getTimestamp()-$at<21600)return array_merge($old,['stale'=>true]);throw $e;}
}
function pp_mackolik_event(array $doc,array $m):?array{$comp=pp_mackolik_competitions()[$m['competitionId']??'']??null;$kick=strtotime($m['kickoff']??'');if(!$comp||!$kick)return null;$found=[];foreach($doc['data']['matches']??[]as$e){if(($e['competitionId']??'')!==$comp||abs((float)($e['mstUtc']??0)/1000-$kick)>=61||!preg_match('/^[a-z0-9]{20,30}$/D',(string)($e['id']??'')))continue;$ok=true;foreach(['home','away']as$side)if(pp_mackolik_name($e[$side.'Team']['name']??'')!==pp_mackolik_name($m[$side]['name']??''))$ok=false;if($ok)$found[]=$e;}return count($found)===1?$found[0]:null;}
function pp_mackolik_text(string $s):string{return trim(preg_replace('/\s+/u',' ',html_entity_decode(strip_tags($s),ENT_QUOTES|ENT_HTML5,'UTF-8')));}
function pp_mackolik_settings(string $html,string $module):?array{if(!preg_match('~<[^>]+data-module="'.preg_quote($module,'~').'"[^>]+data-settings="([^"]*)"~',$html,$m))return null;$j=json_decode(html_entity_decode($m[1],ENT_QUOTES|ENT_HTML5,'UTF-8'),true);return is_array($j)?$j:null;}
function pp_mackolik_header_ok(string $html,array $e):bool{
 $head=pp_mackolik_settings($html,'perform/p0/components/soccer/match/details/header');if(($head['asyncRequestParams']['matchId']??'')!==($e['id']??''))return false;
 if(!preg_match('~class="[^"]*p0c-soccer-match-details-header__info-date[^"]*"[^>]+data-utc="(\d+)"~',$html,$t)||abs((float)$t[1]/1000-(float)($e['mstUtc']??0)/1000)>=61)return false;
 foreach(['home','away']as$side){if(!preg_match('~<img[^>]+class="[^"]*p0c-soccer-match-details-header__team-crest-image--'.$side.'[^>]+src="https://file\.mackolikfeeds\.com/teams/([a-z0-9]+)"[^>]+alt="([^"]*)"~',$html,$t)||$t[1]!==($e[$side.'Team']['id']??'')||pp_mackolik_name(html_entity_decode($t[2],ENT_QUOTES|ENT_HTML5,'UTF-8'))!==pp_mackolik_name($e[$side.'Team']['name']??''))return false;}
 if(!preg_match('~p0c-soccer-match-details-header__competition-link"[^>]+href="[^"]*/([a-z0-9]{20,30})"~',$html,$t)||$t[1]!==($e['competitionId']??''))return false;return true;
}
function pp_mackolik_rows(string $table):array{$out=[];preg_match_all('~<tr\b[^>]*data-person-id="([a-z0-9]{20,30})"[^>]*>(.*?)</tr>~s',$table,$rows,PREG_SET_ORDER);foreach($rows as$r){if(!preg_match('~class="widget-match-stats__person-name"[^>]*>(.*?)</a>~s',$r[2],$n))continue;$name=pp_mackolik_text($n[1]);$number=null;if(preg_match('~class="[^"]*widget-match-stats__cell--shirt-number[^"]*"[^>]*>(.*?)</td>~s',$r[2],$num)&&preg_match('/^\d{1,3}$/D',pp_mackolik_text($num[1])))$number=(int)pp_mackolik_text($num[1]);$out[]=['id'=>$r[1],'name'=>$name,'shirtNumber'=>$number];}return $out;}
function pp_mackolik_lineup_html(string $html,array $e):?array{
 if(!pp_mackolik_header_ok($html,$e))return null;$settings=pp_mackolik_settings($html,'match-stats');if(($settings['asyncRequestParams']['matchId']??'')!==$e['id']||($settings['asyncRequestParams']['ajaxViewName']??'')!=='starting-formation')return null;
 preg_match_all('~<div class="Opta-TeamFormation">([^<]+)</div>~',$html,$forms);if(count($forms[1])!==2)return null;
 // Only the match's starting-formation widget supplies XI; previous-squad is never promoted to confirmed.
 $begin=strpos($html,'data-module="match-stats"');$end=strpos($html,'data-module="match-stats"',$begin+1);$section=substr($html,$begin,$end===false?null:$end-$begin);$probable=(bool)preg_match('/muhtemel|tahmini/iu',pp_mackolik_text($section));$result=['status'=>$probable?'provider-predicted':'provider-lineup','teams'=>[]];
 preg_match_all('~<g class="Opta-Node (Opta-Home|Opta-Away) Opta-Starter">(.*?)(?=<g class="Opta-Node|</svg>)~s',$section,$nodes,PREG_SET_ORDER);$coords=['home'=>[],'away'=>[]];foreach($nodes as$n){$side=$n[1]==='Opta-Home'?'home':'away';if(!preg_match('~Opta-JerseyNumber"[^>]*>(\d{1,3})</text>~',$n[2],$num)||!preg_match('~<circle cx="([\d.]+)" cy="([\d.]+)"~',$n[2],$xy)||!preg_match('~class="Opta-PlayerName"[^>]*>([^<]+)</text>~',$n[2],$name))return null;$x=(float)$xy[1]/832;$y=(float)$xy[2]/556;if($x<0||$x>1||$y<0||$y>1||isset($coords[$side][$num[1]]))return null;$coords[$side][$num[1]]=['name'=>pp_mackolik_text($name[1]),'verticalLayout'=>['x'=>$side==='home'?1-$y:$y,'y'=>$side==='home'?$x:1-$x]];}
 foreach(['home','away']as$i=>$side){preg_match_all('~<table class="widget-match-stats__team widget-match-stats__team--'.$side.'"[^>]*>(.*?)</table>~s',$html,$tables);if(count($tables[1])<2||count($coords[$side])!==11)return null;$players=pp_mackolik_rows($tables[1][0]);if(count($players)!==11)return null;$seen=[];foreach($players as&$p){$n=$p['shirtNumber'];$c=$coords[$side][$n]??null;if(!$c||isset($seen[$n]))return null;$source=preg_split('/\s+/u',$c['name']);$target=preg_split('/\s+/u',$p['name']);if(pp_public_name($c['name'])!==pp_public_name($p['name'])&&pp_public_name((string)end($source))!==pp_public_name((string)end($target)))return null;$seen[$n]=true;$p['verticalLayout']=$c['verticalLayout'];}unset($p);$players=pp_public_roles(trim($forms[1][$i]),$players);if(!$players)return null;$coach=isset($tables[1][2])?pp_mackolik_rows($tables[1][2]):[];$result['teams'][$i]=['formation'=>trim($forms[1][$i]),'players'=>$players,'bench'=>pp_mackolik_rows($tables[1][1]),'coach'=>count($coach)===1?['id'=>'mk-'.$coach[0]['id'],'name'=>$coach[0]['name'],'source'=>'Mackolik']:null];}return $result;
}
function pp_mackolik_enrich(array $m,array $teams,array $cfg,DateTimeImmutable $now,?callable $fetcher=null):array{
 $kick=strtotime($m['kickoff']??'');if(!$kick)return $teams;
 try{$date=(new DateTimeImmutable('@'.$kick))->setTimezone(new DateTimeZone('Europe/Istanbul'))->format('Y-m-d');$day=pp_mackolik_page(pp_mackolik_day_url($date),$cfg,$now,$fetcher);$e=pp_mackolik_event($day['document'],$m);if(!$e)return $teams;$teams=pp_mackolik_club_coaches($e,$m,$teams,$cfg,$now,$fetcher);$page=pp_mackolik_page(pp_mackolik_match_url($e),$cfg,$now,$fetcher);$parsed=pp_mackolik_lineup_html($page['html'],$e);if(!$parsed)return $teams;$actual=$parsed['status']==='provider-lineup';if(!$actual&&$now->getTimestamp()>=$kick)return $teams;
  foreach(['home','away']as$i=>$side){if(($teams[$i]['source']['status']??'')==='provider-lineup'&&(!$actual||$page['stale']||$day['stale']))continue;$pool=array_merge($teams[$i]['players']??[],$teams[$i]['bench']??[]);$raw=$parsed['teams'][$i];$players=[];$bench=[];$seen=[];foreach($raw['players']as$p){$player=pp_misli_player($p,$pool,(string)$e[$side.'Team']['id'],gmdate('Y',$kick),$p['_role']);if(!$player||isset($seen[$player['id']])){$players=[];break;}$seen[$player['id']]=true;$player['providerIds']['mackolik']=$p['id'];if(str_starts_with($player['id'],'ms-'))$player['id']='mk-'.$p['id'];$player['identitySource']='Mackolik match player identity';$players[]=$player;}if(count($players)!==11)continue;foreach($raw['bench']as$p){$player=pp_misli_player($p,$pool,(string)$e[$side.'Team']['id'],gmdate('Y',$kick));if(!$player)continue;if(str_starts_with($player['id'],'ms-'))$player['id']='mk-'.$p['id'];if(isset($seen[$player['id']]))continue;$seen[$player['id']]=true;$player['providerIds']['mackolik']=$p['id'];$bench[]=$player;}
   $teams[$i]=array_merge($teams[$i]??[],['teamId'=>(string)($m[$side]['espnId']??''),'formation'=>$raw['formation'],'players'=>$players,'bench'=>array_slice($bench,0,pp_bench_limit($m['competitionId']??'')),'coach'=>isset($raw['coach'])?($raw['coach']+['asOf'=>$page['fetchedAt'],'basis'=>$actual?'exact-match':'exact-match-probable','url'=>$page['url']]):($teams[$i]['coach']??null),'source'=>['name'=>'Mackolik','status'=>$parsed['status'],'selectionVersion'=>PP_LINEUP_SELECTION_VERSION,'selectionBasis'=>'exact-match-'.($actual?'confirmed':'probable'),'benchStatus'=>$actual?'match-bench':'provider-predicted-bench','asOf'=>$page['fetchedAt'],'url'=>$page['url'],'fixtureUrl'=>$day['url'],'providerMatchId'=>$e['id'],'providerTeamId'=>$e[$side.'Team']['id'],'stale'=>$page['stale']||$day['stale']]]);
  }
 }catch(Throwable $e){/* Public-source failures preserve existing validated lineups. */}return $teams;
}
function pp_mackolik_club_coach(string $html,array $team,string $asOf,string $url):?array{
 $settings=pp_mackolik_settings($html,'perform/p0/components/team/information');if(($settings['asyncRequestParams']['teamId']??'')!==($team['id']??''))return null;
 if(!preg_match('~p0c-team-information__name"[^>]*>(.*?)</span>~s',$html,$n)||pp_mackolik_name(pp_mackolik_text($n[1]))!==pp_mackolik_name($team['name']??''))return null;
 if(!preg_match('~p0c-team-information__item--manager"[^>]*>(.*?)</span>\s*</div>~s',$html,$block))return null;
 if(!preg_match('~<a[^>]+href="https://www\.mackolik\.com/antrenor/[a-zA-Z0-9%_-]+/([a-z0-9]{20,30})"[^>]*>(.*?)</a>~s',$block[1],$c))return null;
 $name=pp_mackolik_text($c[2]);return $name!==''?['id'=>'mk-'.$c[1],'name'=>$name,'source'=>'Maçkolik güncel kulüp','basis'=>'current-club','asOf'=>$asOf,'url'=>$url]:null;
}
function pp_mackolik_club_coaches(array $event,array $m,array $teams,array $cfg,DateTimeImmutable $now,?callable $fetcher=null):array{
 foreach(['home','away']as$i=>$side){$raw=$event[$side.'Team']??[];if(!preg_match('/^[a-zA-Z0-9%_-]{1,180}$/D',$raw['slug']??''))continue;
  try{$url='https://www.mackolik.com/takim/'.$raw['slug'].'/kadro/'.$raw['id'];$p=pp_mackolik_page($url,$cfg,$now,$fetcher);$coach=pp_mackolik_club_coach($p['html'],$raw,$p['fetchedAt'],$url);if(!$coach)continue;$coach['stale']=$p['stale'];pp_current_coach_save($m,$side,$coach,$cfg);if(!empty($teams[$i])&&($teams[$i]['source']['status']??'')!=='provider-lineup')$teams[$i]['coach']=$coach;}catch(Throwable $error){pp_lineup_trace('Mackolik coach','unavailable',$error->getMessage());}
 }return $teams;
}
